const SERVER_INFO = { name: "zk30-mfdb", version: "1.0.0" };
const DEFAULT_PROTOCOL = "2024-11-05";

const TOOLS = [
  { name: "get_overview",
    description: "Executive overview of the ZK30 MFDB: reporting period, execution flow and activity summary (meetings, touchpoints, SP3B queue, conversion note).",
    inputSchema: { type: "object", properties: {} } },
  { name: "get_top_priorities",
    description: "The current Top 10 executive priority board for ZK30 MFDB.",
    inputSchema: { type: "object", properties: {} } },
  { name: "list_lexa",
    description: "List LEXA relationship/account records. Optional filters.",
    inputSchema: { type: "object", properties: {
      query: { type: "string", description: "Case-insensitive text match across org, status, next action, engagement." },
      status: { type: "string", description: "Filter by status (e.g. Proposal Due, Meeting Due, Running)." },
      cluster: { type: "string", description: "Filter by cluster (e.g. Government, Cooperative, SME)." },
      top10: { type: "boolean", description: "If true, only ranked Top-10 accounts." },
      limit: { type: "number", description: "Max records (default 25)." }
    } } },
  { name: "get_lexa",
    description: "Get one LEXA account in full by LEXA id (e.g. LEXA-001) or by organisation name.",
    inputSchema: { type: "object", properties: { id_or_name: { type: "string" } }, required: ["id_or_name"] } },
  { name: "search",
    description: "Free-text search across all ZK30 MFDB LEXA records; returns the best matches.",
    inputSchema: { type: "object", properties: { query: { type: "string" } }, required: ["query"] } }
];

function text(t) { return { content: [{ type: "text", text: t }] }; }

function runTool(name, args) {
  args = args || {};
  if (name === "get_overview") {
    const a = DATA.activity;
    return text([
      "ZK30 MFDB Command Centre - Overview",
      "Last updated: " + DATA.generatedAt,
      "Period: " + (a.period || ""),
      "Execution flow: " + DATA.executionFlow,
      "",
      "Meetings: " + (a.meetings || ""),
      "Touchpoints: " + (a.touchpoints || ""),
      "Completed/Submitted: " + (a.sp3bCompleted || ""),
      "SP3B queue: " + (a.sp3bQueue || ""),
      "Note: " + (a.conversionNote || ""),
      "",
      "Total LEXA accounts: " + DATA.lexa.length
    ].join("\n"));
  }
  if (name === "get_top_priorities") {
    return text("ZK30 MFDB - Top 10 Priorities (" + DATA.generatedAt + ")\n\n" +
      DATA.priorities.map(p => p.label + ": " + p.text).join("\n"));
  }
  if (name === "get_lexa") {
    const q = String(args.id_or_name || "").trim().toLowerCase();
    const r = DATA.lexa.find(x => x.id.toLowerCase() === q) ||
              DATA.lexa.find(x => x.org.toLowerCase() === q) ||
              DATA.lexa.find(x => x.org.toLowerCase().includes(q));
    if (!r) return text("No LEXA account found for: " + args.id_or_name);
    return text([
      r.id + " - " + r.org,
      "Cluster: " + r.cluster + " | Priority: " + (r.priority || "-") + " | Opportunity: " + r.opportunity + (r.rank ? " | Top-10 rank: " + r.rank : ""),
      "Key persons: " + (r.keyPersons || "-"),
      "Status: " + r.status,
      "Next action: " + r.nextAction,
      "Expected outcome: " + r.outcome,
      "Last engagement: " + r.lastEngagement,
      "Next follow-up: " + (r.nextFollowUp || "-")
    ].join("\n"));
  }
  if (name === "list_lexa" || name === "search") {
    let rows = DATA.lexa.slice();
    const query = String((name === "search" ? args.query : args.query) || "").trim().toLowerCase();
    if (name === "list_lexa" && args.top10) rows = rows.filter(r => r.rank);
    if (name === "list_lexa" && args.status) rows = rows.filter(r => (r.status || "").toLowerCase() === String(args.status).toLowerCase());
    if (name === "list_lexa" && args.cluster) rows = rows.filter(r => (r.cluster || "").toLowerCase() === String(args.cluster).toLowerCase());
    if (query) rows = rows.filter(r => (r.id + " " + r.org + " " + r.cluster + " " + r.keyPersons + " " + r.status + " " + r.nextAction + " " + r.outcome + " " + r.lastEngagement).toLowerCase().includes(query));
    rows.sort((a, b) => (a.rank || 999) - (b.rank || 999));
    const limit = Math.min(Number(args.limit) || (name === "search" ? 15 : 25), 100);
    const out = rows.slice(0, limit).map(r => (r.rank ? "#" + r.rank + " " : "") + r.id + " " + r.org + " [" + r.status + "] - " + r.nextAction);
    return text(rows.length + " match(es)" + (rows.length > limit ? " (showing " + limit + ")" : "") + ":\n\n" + out.join("\n"));
  }
  return text("Unknown tool: " + name);
}

function cors(extra) {
  return Object.assign({
    "access-control-allow-origin": "*",
    "access-control-allow-methods": "GET,POST,OPTIONS",
    "access-control-allow-headers": "content-type,authorization,mcp-session-id,mcp-protocol-version",
    "content-type": "application/json"
  }, extra || {});
}
function rpc(id, result) { return { jsonrpc: "2.0", id: id === undefined ? null : id, result }; }
function rpcErr(id, code, message) { return { jsonrpc: "2.0", id: id === undefined ? null : id, error: { code, message } }; }

function handleOne(msg) {
  const { id, method, params } = msg || {};
  if (method === "initialize") {
    const pv = (params && params.protocolVersion) || DEFAULT_PROTOCOL;
    return rpc(id, { protocolVersion: pv, capabilities: { tools: {} }, serverInfo: SERVER_INFO,
      instructions: "ZK30 MFDB Command Centre. Read-only access to LEXA accounts, top priorities and executive overview." });
  }
  if (method === "ping") return rpc(id, {});
  if (method === "tools/list") return rpc(id, { tools: TOOLS });
  if (method === "tools/call") {
    const nm = params && params.name;
    if (!TOOLS.some(t => t.name === nm)) return rpcErr(id, -32602, "Unknown tool: " + nm);
    try { return rpc(id, runTool(nm, (params && params.arguments) || {})); }
    catch (e) { return rpc(id, Object.assign(text("Error: " + String(e)), { isError: true })); }
  }
  if (method && method.indexOf("notifications/") === 0) return null; // no response for notifications
  if (id === undefined) return null;
  return rpcErr(id, -32601, "Method not found: " + method);
}

export default async (req) => {
  if (req.method === "OPTIONS") return new Response("", { status: 204, headers: cors() });

  // Optional bearer/key auth
  const token = process.env.MCP_TOKEN;
  if (token) {
    const auth = req.headers.get("authorization") || "";
    const url0 = new URL(req.url);
    const key = url0.searchParams.get("key") || "";
    const supplied = auth.replace(/^Bearer\s+/i, "") || key;
    if (supplied !== token) return new Response(JSON.stringify({ error: "unauthorized" }), { status: 401, headers: cors() });
  }

  if (req.method === "GET") {
    return new Response(JSON.stringify({ server: SERVER_INFO, transport: "streamable-http", protocol: DEFAULT_PROTOCOL,
      note: "POST JSON-RPC 2.0 to this endpoint. Tools: " + TOOLS.map(t => t.name).join(", ") }), { status: 200, headers: cors() });
  }
  if (req.method !== "POST") return new Response("Method Not Allowed", { status: 405, headers: cors() });

  let body;
  try { body = await req.json(); } catch (e) { return new Response(JSON.stringify(rpcErr(null, -32700, "Parse error")), { status: 200, headers: cors() }); }

  if (Array.isArray(body)) {
    const out = body.map(handleOne).filter(Boolean);
    return new Response(out.length ? JSON.stringify(out) : "", { status: out.length ? 200 : 202, headers: cors() });
  }
  const res = handleOne(body);
  return new Response(res ? JSON.stringify(res) : "", { status: res ? 200 : 202, headers: cors() });
};

export const config = { path: "/mcp" };
